<script setup lang="ts">
import {ref,computed,watch,onMounted,onBeforeUnmount,nextTick} from 'vue';
import {api} from '../api';import {useWorkspace,type WorkTab} from '../stores';import {loadGoogleMaps,mapPosition} from '../google-maps';
const props=defineProps<{tab:WorkTab}>(),work=useWorkspace(),data=ref<any>(null),search=ref(''),inactive=ref(false),selected=ref(''),loading=ref(false),mapLoading=ref(false),error=ref(''),mapError=ref(''),canvas=ref<HTMLElement|null>(null);
let sdk:any=null,map:any=null,info:any=null,markers=new Map<string,any>(),sequence=0,disposed=false,observer:ResizeObserver|null=null;
const positioned=computed(()=>(data.value?.stores||[]).filter((s:any)=>mapPosition(s)));
const visible=computed(()=>positioned.value.filter((s:any)=>[s.store_code,s.store_name,s.short_name,s.address,s.phone].join(' ').toLowerCase().includes(search.value.trim().toLowerCase())));
const current=computed(()=>visible.value.find((s:any)=>s.id===selected.value));
const mapsLink=computed(()=>{const p=mapPosition(current.value);return p?'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(p.lat+','+p.lng):'';});
function waitForTiles(){return new Promise<void>((resolve,reject)=>{let listener:any;const finish=(message?:string)=>{clearTimeout(timer);listener?.remove();window.removeEventListener('workspace-maps-auth-error',failed);message?reject(new Error(message)):resolve();};const failed=()=>finish('Google 地圖授權未通過，請聯絡管理員確認網站設定。');const timer=window.setTimeout(()=>finish('Google 底圖載入逾時，請確認網路後重試。'),15000);window.addEventListener('workspace-maps-auth-error',failed);listener=sdk.event.addListenerOnce(map,'tilesloaded',()=>finish());});}
function clearMarkers(){for(const marker of markers.values()){sdk?.event.clearInstanceListeners(marker);marker.map=null;}markers.clear();info?.close();}
function fit(){if(!map||!sdk||!visible.value.length)return;const bounds=new sdk.LatLngBounds();visible.value.forEach((s:any)=>bounds.extend(mapPosition(s)));map.fitBounds(bounds);if(visible.value.length===1)map.setZoom(16);}
function focus(id:string){selected.value=id;const s=current.value,marker=markers.get(id);if(!s||!marker||!map)return;map.panTo(mapPosition(s));map.setZoom(Math.max(map.getZoom()||15,15));const content=document.createElement('div');content.className='map-info';for(const text of [s.store_code+' '+s.store_name,s.address,s.phone,s.is_active?'營運中':'已停止']){if(!text)continue;const line=document.createElement('p');line.textContent=text;content.append(line);}info.setContent(content);info.open({map,anchor:marker});}
function draw(){clearMarkers();if(!map||!sdk)return;for(const store of visible.value){const marker=new sdk.AdvancedMarkerElement({map,position:mapPosition(store),title:store.store_code+' '+store.store_name});marker.addListener('click',()=>focus(store.id));markers.set(store.id,marker);}if(!visible.value.some((s:any)=>s.id===selected.value))selected.value=visible.value[0]?.id||'';fit();}
async function renderMap(){if(disposed||!data.value||!positioned.value.length||!canvas.value)return;const token=++sequence;mapLoading.value=true;mapError.value='';try{sdk=await loadGoogleMaps(data.value.apiKey);if(disposed||token!==sequence||!canvas.value)return;if(!map){map=new sdk.Map(canvas.value,{center:{lat:23.6978,lng:120.9605},zoom:8,mapId:data.value.mapId,mapTypeControl:false,streetViewControl:false,fullscreenControl:true});info=new sdk.InfoWindow();}const ready=waitForTiles();draw();await ready;}catch(e){if(!disposed&&token===sequence)mapError.value=(e as Error).message;}finally{if(!disposed&&token===sequence)mapLoading.value=false;}}
async function load(){if(loading.value)return;loading.value=true;error.value='';try{data.value=await api('store-map?inactive='+inactive.value);if(disposed)return;await nextTick();await renderMap();}catch(e){data.value=null;clearMarkers();error.value=(e as Error).message;}finally{loading.value=false;}}
function authError(){mapError.value='Google 地圖授權未通過，請聯絡管理員確認網站設定。';mapLoading.value=false;}
watch(visible,()=>{if(!visible.value.some((s:any)=>s.id===selected.value))selected.value=visible.value[0]?.id||'';draw();});
watch(()=>work.active,async id=>{if(id===props.tab.id){await nextTick();if(map){sdk.event.trigger(map,'resize');fit();}}});
onMounted(()=>{window.addEventListener('workspace-maps-auth-error',authError);observer=new ResizeObserver(()=>{if(map&&work.active===props.tab.id)sdk.event.trigger(map,'resize');});if(canvas.value)observer.observe(canvas.value);load();});
onBeforeUnmount(()=>{disposed=true;sequence++;clearMarkers();if(map)sdk?.event.clearInstanceListeners(map);observer?.disconnect();window.removeEventListener('workspace-maps-auth-error',authError);map=null;info=null;});
</script>
<template>
<header class="page-heading"><div><p class="eyebrow">組織與門市 / 門市位置</p><h1>門市整合地圖</h1></div><div class="module-actions"><button @click="fit" :disabled="!visible.length||!!mapError||mapLoading">顯示全部搜尋結果</button><button @click="load" :disabled="loading">重新整理</button></div></header>
<p v-if="error" class="notice error" role="alert">{{error}}</p><p v-if="loading&&!data" role="status">載入門市位置…</p>
<div class="map-filters"><label>搜尋門市位置<input v-model="search" placeholder="代碼、名稱、簡稱、地址或電話"></label><label v-if="data?.canInactive" class="check"><input type="checkbox" v-model="inactive" :disabled="loading" @change="load">顯示已停止門市</label></div>
<p v-if="data" class="muted">已設定有效 GPS {{positioned.length}} 間 · 尚無有效定位 {{data.stores.length-positioned.length}} 間 · 搜尋結果 {{visible.length}} 間</p>
<div class="store-map-layout"><div class="map-stores" aria-label="地圖門市清單"><button v-for="store in visible" :key="store.id" class="map-store" :aria-pressed="selected===store.id" @click="focus(store.id)"><strong>{{store.store_code}} {{store.short_name||store.store_name}}</strong><span>{{store.address||'未提供地址'}}</span><small>{{store.is_active?'營運中':'已停止'}} · {{store.phone||'未提供電話'}}</small></button><p v-if="data&&!visible.length" class="map-empty">{{positioned.length?'沒有符合搜尋條件的門市。':'尚無可查看且已設定有效 GPS 的門市。'}}</p></div>
<div class="map-area"><div ref="canvas" class="google-map-canvas" :class="{'map-hidden':!!mapError||!visible.length}" aria-label="門市 Google 地圖"></div><div v-if="mapLoading||mapError||!visible.length" class="map-message"><p v-if="mapLoading" role="status">載入 Google 地圖…</p><template v-if="mapError"><p role="alert">{{mapError}}</p><button @click="renderMap" :disabled="mapLoading">重試載入地圖</button></template><p v-else-if="!mapLoading&&!visible.length">{{positioned.length?'目前搜尋範圍沒有門市位置。':'有門市設定有效 GPS 後，會在此顯示位置。'}}</p></div></div></div>
<section v-if="current" class="map-selection" aria-label="選取門市資訊"><h2>{{current.store_code}} {{current.store_name}}</h2><p>{{current.address||'未提供地址'}} · {{current.phone||'未提供電話'}}</p><p>{{mapPosition(current)?.lat}}, {{mapPosition(current)?.lng}} · {{current.is_active?'營運中':'已停止'}}</p><a :href="mapsLink" target="_blank" rel="noopener noreferrer">在 Google Maps 開啟 ↗</a></section>
</template>
<style scoped>.map-filters{display:flex;align-items:end;gap:20px;flex-wrap:wrap}.map-filters label{display:grid;gap:8px;min-width:260px}.map-filters .check{display:flex;align-items:center;min-width:0;padding:10px}.check input{width:18px;height:18px;min-width:18px;min-height:18px}.store-map-layout{display:grid;grid-template-columns:minmax(240px,.65fr) minmax(0,1.35fr);border-block:1px solid var(--line)}.map-stores{max-height:600px;overflow:auto;border-right:1px solid var(--line)}.map-store{display:grid;width:100%;gap:8px;text-align:left;border:0;border-bottom:1px solid var(--line);border-radius:0;padding:16px;white-space:normal;overflow-wrap:anywhere}.map-store[aria-pressed=true]{background:var(--hover,#e9eedf);border-left:4px solid var(--primary)}.map-store span,.map-store small{font-weight:normal;color:var(--muted)}.map-area{position:relative;min-width:0;min-height:520px}.google-map-canvas{height:600px;width:100%}.map-hidden{visibility:hidden}.map-message{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;padding:24px;text-align:center;background:var(--surface,#fff)}.map-selection{padding:20px 0;overflow-wrap:anywhere}.map-selection h2{font-size:18px}.map-selection a{text-decoration:underline}.map-empty{padding:20px}@media(max-width:800px){.store-map-layout{grid-template-columns:1fr}.map-stores{max-height:250px;border-right:0}.map-area{min-height:380px}.google-map-canvas{height:380px}.map-filters label{min-width:0;width:100%}}</style>
